"""Apply backend tracing, metrics, and Langfuse once per process.

The CLI parent resolves these settings in ``configure_commandline``. Sanic
spawn workers start as fresh interpreters and never run that hook, so the
parent ships the applied settings to each worker through ``ServeConfig``.
"""

from __future__ import annotations

import asyncio
from typing import Optional, Text

import structlog
from pydantic import BaseModel, ConfigDict

structlogger = structlog.get_logger()

_FLUSH_TIMEOUT_MILLIS = 5000

_applied_settings: Optional[ObservabilitySettings] = None


class ObservabilitySettings(BaseModel):
    """Resolved inputs for backend tracing, metrics, and Langfuse.

    Picklable so it can cross the spawn boundary inside ``ServeConfig``.
    """

    model_config = ConfigDict(frozen=True)

    project_root: Text
    endpoints_file: Optional[Text] = None
    is_mantle: bool = False
    langfuse_environment_name: Optional[Text] = None


def configure_process_observability(settings: ObservabilitySettings) -> None:
    """Configure backend tracing, metrics, and Langfuse for this process.

    Records *settings* as applied before configuring, so a worker that fails
    part-way does not retry against providers that are already registered.

    Args:
        settings: The resolved project root, endpoints file, engine, and
            optional Langfuse environment override.
    """
    # Lazy imports: these modules import the agent and processor stack.
    from rasa.tracing.backend_tracing_config import (
        configure_backend_tracing_for_project,
    )
    from rasa.tracing.langfuse_config import configure_langfuse_for_project
    from rasa.tracing.metrics_config import configure_metrics_for_project

    global _applied_settings
    _applied_settings = settings

    configure_backend_tracing_for_project(
        project_root=settings.project_root,
        endpoints_file=settings.endpoints_file,
        is_mantle=settings.is_mantle,
    )
    configure_metrics_for_project(
        project_root=settings.project_root,
        endpoints_file=settings.endpoints_file,
        is_mantle=settings.is_mantle,
    )
    configure_langfuse_for_project(
        settings.endpoints_file,
        project_root=settings.project_root,
        is_mantle=settings.is_mantle,
        langfuse_environment_name=settings.langfuse_environment_name,
    )


def applied_process_observability() -> Optional[ObservabilitySettings]:
    """Return the settings this process applied, or ``None`` if none were."""
    return _applied_settings


async def flush_process_observability() -> None:
    """Export buffered spans and metrics before the process stops.

    Best effort and bounded: a slow or unreachable collector is logged and
    never blocks server shutdown past the timeout.
    """
    from opentelemetry import metrics, trace

    for provider in (trace.get_tracer_provider(), metrics.get_meter_provider()):
        force_flush = getattr(provider, "force_flush", None)
        if force_flush is None:
            continue
        try:
            await asyncio.to_thread(force_flush, _FLUSH_TIMEOUT_MILLIS)
        except Exception as exc:
            structlogger.warning(
                "observability.flush_failed",
                event_info="Failed to flush telemetry on shutdown.",
                provider=type(provider).__name__,
                exc_info=exc,
            )
